// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        bound(amount, 1, 100 ether);

        vm.deal(address(c), 100 ether);

        uint256 balanceBefore = address(c).balance;

        vm.prank(c.owner());
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));

        if (ok) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceBefore - balanceAfter == amount);
        } else {
            assertTrue(true);
        }
    }
}
